    "Confidential evidence drop for construction laborers, truck operators, and vigilant citizens. Earn a 10% statutory recovery bounty on seized contractor bank guarantees with zero identity disclosure.": "निर्माण श्रमिकों, वाहन चालकों और सतर्क नागरिकों के लिए गोपनीय साक्ष्य केंद्र। बिना पहचान उजागर किए जब्त ठेकेदार बैंक गारंटी पर 10% कानूनी वसूली इनाम प्राप्त करें।",
    "This channel does NOT record your name, phone number, or IP address. EXIF camera metadata is scrubbed automatically in your browser. Upon submission, you will receive a private 12-word cryptographic claim phrase. You will use this phrase to claim your cash bounty anonymously.": "यह चैनल आपका नाम, मोबाइल नंबर या आईपी एड्रेस कभी रिकॉर्ड नहीं करता। आपके ब्राउज़र में ही कैमरे का EXIF मेटाडेटा स्वतः हटा दिया जाता है। शिकायत दर्ज करने पर आपको 12-शब्दों की एक गुप्त कुंजी मिलेगी, जिसका उपयोग आप बिना पहचान बताए अपना 10% नकद इनाम प्राप्त करने के लिए करेंगे।",
    "Dedicated on-site voice assistant: Speak your observation or listen to step-by-step audio guidance.": "साइट श्रमिकों और आम नागरिकों के लिए वॉइस सुविधा: आप हिंदी में बोलकर सीधे अपनी शिकायत दर्ज कर सकते हैं या ऑडियो निर्देश सुन सकते हैं।",
