    "Statutory evidence protocol: Camera and proof uploads require active device GPS to prevent falsified reports. Coordinates link the contractor and invoke the 36-month Defect Liability Period (DLP).": "आधिकारिक साक्ष्य नियम: गलत शिकायतों को रोकने के लिए फोटो एवं वीडियो अपलोड हेतु मोबाइल GPS चालू होना अनिवार्य है। इससे ठेकेदार की 36 माह की दोष दायित्व अवधि (DLP) सीधे लागू होती है।",
