    "Claim 10% Bounty": "10% బహుమతిని క్లెయిమ్ చేయండి",
    "Confidential evidence drop for construction laborers, truck operators, and vigilant citizens. Earn a 10% statutory recovery bounty on seized contractor bank guarantees with zero identity disclosure.": "నిర్మాణ కార్మికులు, డ్రైవర్లు మరియు అప్రమత్త పౌరుల కోసం రహస్య సాక్ష్యాల వేదిక. గుర్తింపు బహిర్గతం కాకుండానే స్వాధీనం చేసుకున్న కాంట్రాక్టర్ బ్యాంక్ గ్యారంటీపై 10% చట్టబద్ధమైన నగదు బహుమతిని పొందండి.",
    "This channel does NOT record your name, phone number, or IP address. EXIF camera metadata is scrubbed automatically in your browser. Upon submission, you will receive a private 12-word cryptographic claim phrase. You will use this phrase to claim your cash bounty anonymously.": "ఈ పోర్టల్ మీ పేరు, ఫోన్ నంబర్ లేదా IP చిరునామాను ఎప్పటికీ సేకరించదు. మీ బ్రౌజర్‌లోనే కెమెరా EXIF మెటాడేటా స్వయంచాలకంగా తొలగించబడుతుంది. సమర్పించిన తర్వాత మీకు 12 పదాల క్రిప్టోగ్రాఫిక్ క్లెయిమ్ కోడ్ లభిస్తుంది. దీని ద్వారా మీ గుర్తింపు చెప్పకుండానే నగదు బహుమతిని క్లెయిమ్ చేసుకోవచ్చు.",
    "Dedicated on-site voice assistant: Speak your observation or listen to step-by-step audio guidance.": "సైట్ లో పనిచేసే కార్మికులు మరియు ప్రజల కోసం ప్రత్యేక వాయిస్ సదుపాయం: మీరు తెలుగులో మాట్లాడి నేరుగా ఫిర్యాదు చేయవచ్చు లేదా ఆడియో సూచనలను వినవచ్చు.",
    "Listen Voice Guide": "వినండి (వాయిస్ గైడ్)",
    "Stop Voice Guide": "ఆడియో ఆపండి",
    "Speak to Report": "మాట్లాడి ఫిర్యాదు చెప్పండి",
    "Listening...": "వింటున్నారు... మాట్లాడండి",
