    "Whistleblower Statutory Protections": "విజిలెన్స్ చట్టపరమైన రక్షణలు (కేంద్ర నిఘా కమిషన్ CVC నిబంధనలు)",
    "Under the Central Vigilance Commission (CVC) Act and National Whistleblowers Protection norms:": "కేంద్ర నిఘా కమిషన్ (CVC) చట్టం మరియు జాతీయ విజిలెన్స్ రక్షణ నిబంధనల ప్రకారం:",
