    "Statutory 10% Bounty:": "10% చట్టబద్ధమైన నగదు బహుమతి:",
    "10% of seized Performance Bank Guarantees (PBG) paid to the informant.": "కాంట్రాక్టర్ వద్ద స్వాధీనం చేసుకున్న బ్యాంక్ గ్యారంటీలో 10% మీకు చెల్లించబడుతుంది.",
