    "Tell us if work is stopped, delayed, or poor quality materials are being used.": "పని ఆగిపోయిందా లేదా నాసిరకం మెటీరియల్స్ వాడుతున్నారా చెప్పండి.",
    "Take a photo or video. Your location ensures the proof is genuine.": "ఫోటో లేదా వీడియో తీయండి. మీ స్థానం ద్వారా సాక్ష్యం నిజమైనదని ధృవీకరించబడుతుంది.",
    "Receive a tracking ID. Local engineers are dispatched to inspect and resolve it.": "ట్రాకింగ్ ఐడీని పొందండి. సమస్య పరిష్కారానికి అధికారులను వెంటనే పంపడం జరుగుతుంది.",
    "Statutory evidence protocol: Camera and proof uploads require active device GPS to prevent falsified reports. Coordinates link the contractor and invoke the 36-month Defect Liability Period (DLP).": "చట్టబద్ధమైన సాక్ష్య నిబంధన: నకిలీ ఫిర్యాదులను అరికట్టడానికి కెమెరా మరియు ఫోటో అప్‌లోడ్ కొరకు GPS ఆన్ లో ఉండటం తప్పనిసరి. కోఆర్డినేట్లు కాంట్రాక్టర్ బాధ్యతను మరియు 36 నెలల ఉచిత మరమ్మతు వ్యవధి (DLP)ని అమలు చేస్తాయి.",
