    "Your 12-Word Secret Bounty Claim Key": "మీ 12-పదాల రహస్య రివార్డ్ క్లెయిమ్ కీ",
    "Your submission has been sealed with zero-knowledge cryptography. No name, phone number, or identity was stored. Write down or copy this 12-word seed phrase. It is your only cryptographic proof to claim your 10% cash bounty when penalties are recovered.": "మీ సమర్పణ జీరో-నాలెడ్జ్ క్రిప్టోగ్రఫీతో భద్రపరచబడింది. పేరు, ఫోన్ నంబర్ లేదా గుర్తింపు నిల్వ చేయబడలేదు. ఈ 12-పదాల పదబంధాన్ని రాసుకోండి లేదా కాపీ చేయండి. జరిమానాలు వసూలైనప్పుడు మీ 10% నగదు బహుమతిని క్లెయిమ్ చేయడానికి ఇది మీ ఏకైక క్రిప్టోగ్రాఫిక్ రుజువు.",
