    "Because this system is 100% anonymous, this key cannot be recovered via email or phone. Keep it secret and safe.": "ఈ వ్యవస్థ 100% అనామకమైనది కాబట్టి, ఈ కీని ఇమెయిల్ లేదా ఫోన్ ద్వారా తిరిగి పొందలేరు. దీనిని రహస్యంగా మరియు సురక్షಿತంగా ఉంచండి.",
