    "Grievance Redressal Timeline (What Is Happening Now)": "குறைதீர்க்கும் காலவரிசை (தற்போது நடப்பது)",
    "Step 1: Registered ✓": "படி 1: பதிவு செய்யப்பட்டது ✓",
    "Photo & location logged into system": "புகைப்படம் மற்றும் இடம் அமைப்பில் பதிவு செய்யப்பட்டது",
    "Step 2: Officer Assigned ✓": "படி 2: அதிகாரி நியமிக்கப்பட்டார் ✓",
    "Local engineering wing notified": "உள்ளூர் பொறியியல் பிரிவுக்கு தெரிவிக்கப்பட்டது",
