    "Step 4: Resolved": "படி 4: தீர்க்கப்பட்டது",
    "Work resumed & defect repaired": "வேலை மீண்டும் தொடங்கப்பட்டு குறைபாடு சரிசெய்யப்பட்டது",
    "Assigned Investigation Officer:": "நியமிக்கப்பட்ட விசாரணை அதிகாரி:",
    "Target Public Asset ID:": "பொது சொத்து ஐடி:",
    "Official Redressal Remarks / Action Taken:": "அதிகாரப்பூர்வ தீர்வு கருத்துக்கள் / எடுக்கப்பட்ட நடவடிக்கை:",
    "Defect notice issued to contractor. Assigned to Superintending Engineer PWD for site inspection.": "ஒப்பந்தக்காரருக்கு குறைபாடு நோட்டீஸ் அனுப்பப்பட்டது. கள ஆய்வுக்கு PWD கண்காணிப்பு பொறியாளரிடம் ஒப்படைக்கப்பட்டது.",
    "Submitted Geotagged Photographic Proof:": "சமர்ப்பிக்கப்பட்ட ஜியோடேக் புகைப்பட ஆதாரம்:",
    "View Public Work Dossier": "பொதுப் பணி ஆவணத்தைப் பார்க்கவும்",
    "Inspect in Higher Officials Alert Engine": "உயர் அதிகாரிகள் எச்சரிக்கை அமைப்பில் ஆய்வு செய்க",
    "Select a Grievance or Search Above": "ஒரு புகாரைத் தேர்ந்தெடுக்கவும் அல்லது மேலே தேடவும்",
    "You can click on any complaint from the \"Recent Grievance Submissions\" list on the right, or enter your Tracking ID above.": "வலதுபுறத்தில் உள்ள 'சமீபத்திய புகார்கள்' பட்டியலிலிருந்து எந்தவொரு புகாரையும் கிளிக் செய்யலாம் அல்லது மேலே உங்கள் டிராக்கிங் ஐடியை உள்ளிடலாம்.",
    "Grievance Registered Successfully": "புகார் வெற்றிகரமாக பதிவு செய்யப்பட்டது",
    "Complaint Tracking ID:": "புகார் கண்காணிப்பு ஐடி:",
    "Grievance Redressal Lifecycle:": "குறைதீர்க்கும் சுழற்சி:",
    "1. Submitted ✓": "1. சமர்ப்பிக்கப்பட்டது ✓",
