    "View Related Public Work": "தொடர்புடைய பொதுப் பணியைப் பார்க்கவும்",
    "View Higher Officials Escalation Alert": "உயர் அதிகாரிகள் எச்சரிக்கையைப் பார்க்கவும்",
    "Report Another Issue": "மற்றொரு சிக்கலைப் புகாரளிக்கவும்",
    "Active 36-Mo Guarantee": "செயலில் உள்ள 36-மாத உத்தரவாதம்",
    "Responsible Contractor:": "பொறுப்பான ஒப்பந்தக்காரர்:",
    "Guarantee Protection:": "உத்தரவாத பாதுகாப்பு:",
    "3-Year Free Defect Repair": "3 ஆண்டுகள் இலவச குறைபாடு பழுதுபார்ப்பு",
    "Contractor legally required to fix defects": "குறைபாடுகளை சரிசெய்ய ஒப்பந்தக்காரர் சட்டப்படி கடமைப்பட்டவர்",
    "Performance Bank Guarantee (PBG):": "செயல்திறன் வங்கி உத்தரவாதம் (PBG):",
    "Subject to immediate freeze upon defect notice": "குறைபாடு அறிவிப்பு வந்தவுடன் உடனடியாக முடக்கப்படும்",
    "Transmitting Encrypted Geotag & Invoking DLP...": "மறைகுறியாக்கப்பட்ட ஜியோடேக் அனுப்பப்பட்டு DLP செயல்படுத்தப்படுகிறது...",
    "⚡ File Statutory Defect Notice & Freeze Contractor Guarantee": "⚡ சட்டப்பூர்வ குறைபாடு நோட்டீஸ் அளித்து ஒப்பந்தக்காரர் உத்தரவாதத்தை முடக்கு",
    "Track Status": "நிலையைக் கண்காணிக்கவும்",
    "Work": "பணி",
    "Live Incident Proof Camera & Geotagger": "நேரலை சம்பவ ஆதார கேமரா & ஜியோடேக்கர்",
    "GPS SERVICE OFF • Evidence Capture Disabled": "ஜிபிஎஸ் சேவை முடக்கப்பட்டுள்ளது • ஆதாரப் பதிவு நிறுத்தப்பட்டது",
    "Switch between front and back camera": "முன் மற்றும் பின் கேமரா இடையே மாறவும்",
    "Flip": "திருப்பு",
    "Close Camera": "கேமராவை மூடு",
    "Connecting to device camera sensor...": "சாதன கேமரா சென்சாருடன் இணைகிறது...",
    "Please tap \"Allow\" if your browser prompts for camera permission": "கேமரா அனுமதி கேட்கப்பட்டால் தயவுசெய்து \"Allow\" என்பதைத் தட்டவும்",
    "Camera Notice": "கேமரா அறிவிப்பு",
    "Retry Camera": "மீண்டும் கேமராவை முயற்சிக்கவும்",
    "Align Defect / Damage Inside Frame": "குறைபாடு / சேதத்தை சட்டகத்திற்குள் சீரமைக்கவும்",
    "GPS Signal Missing / Location OFF": "ஜிபிஎஸ் சிக்னல் இல்லை / இருப்பிடம் முடக்கப்பட்டுள்ளது",
    "You cannot take photos or record videos while device GPS is turned off. Statutory audit rules require active GPS coordinates.": "சாதனத்தின் ஜிபிஎஸ் முடக்கப்பட்டிருக்கும் போது புகைப்படங்கள் அல்லது வீடியோக்களை எடுக்க முடியாது. தணிக்கை விதிகளுக்கு நேரடி ஜிபிஎஸ் தேவை.",
    "Turn ON GPS / Retry Location": "ஜிபிஎஸ் இயக்கவும் / இருப்பிடத்தை மீண்டும் முயற்சிக்கவும்",
    "GPS is required to take photos": "புகைப்படம் எடுக்க ஜிபிஎஸ் தேவை",
    "Capture geotagged photo": "ஜியோடேக் செய்யப்பட்ட புகைப்படத்தை எடுக்கவும்",
    "Take Photo": "புகைப்படம் எடு",
