    "Encrypted Evidence Sealed": "மறைகுறியாக்கப்பட்ட ஆதாரம் பாதுகாக்கப்பட்டது",
    "Your 12-Word Secret Bounty Claim Key": "உங்கள் 12-சொல் ரகசிய வெகுமதி உரிமைக்கான சாவி",
    "Your submission has been sealed with zero-knowledge cryptography. No name, phone number, or identity was stored. Write down or copy this 12-word seed phrase. It is your only cryptographic proof to claim your 10% cash bounty when penalties are recovered.": "உங்கள் சமர்ப்பிப்பு பூஜ்ஜிய-அறிவு குறியாக்கவியலுடன் பாதுகாக்கப்பட்டுள்ளது. பெயர், தொலைபேசி எண் அல்லது அடையாளம் எதுவும் சேமிக்கப்படவில்லை. இந்த 12-சொல் சொற்றொடரை குறித்துக்கொள்ளவும். அபராதம் வசூலிக்கப்படும்போது உங்கள் 10% ரொக்க வெகுமதியைப் பெறுவதற்கான ஒரே கிரிப்டோக్రాஃபிக் ஆதாரம் இதுவே.",
    "Do Not Lose This Phrase:": "இந்த சொற்றொடரை இழக்காதீர்கள்:",
    "Because this system is 100% anonymous, this key cannot be recovered via email or phone. Keep it secret and safe.": "இந்த அமைப்பு 100% அநாமதேயமானது என்பதால், இந்த சாவியை மின்னஞ்சல் அல்லது தொலைபேசி மூலம் மீட்டெடுக்க முடியாது. இதை ரகசியமாகவும் பாதுகாப்பாகவும் வைத்திருங்கள்.",
    "Copy 12 Words": "12 சொற்களை நகலெடுக்கவும்",
    "I Have Saved My Secret Phrase": "எனது ரகசிய சொற்றொடரை நான் சேமித்துவிட்டேன்",
    "Tagarapuvalasa Site Perimeter": "தகரபுவலசா பணித்தள சுற்றளவு",
