    "Confidential evidence drop for construction laborers, truck operators, and vigilant citizens. Earn a 10% statutory recovery bounty on seized contractor bank guarantees with zero identity disclosure.": "নির্মাণ শ্রমিক, চালক এবং সতর্ক নাগরিকদের জন্য গোপন প্রমাণ কেন্দ্র। কোনো পরিচয় প্রকাশ না করে বাজেয়াপ্ত ঠিকাদার ব্যাংক গ্যারান্টির ওপর ১০% বিধিবদ্ধ নগদ পুরস্কার অর্জন করুন।",
    "This channel does NOT record your name, phone number, or IP address. EXIF camera metadata is scrubbed automatically in your browser. Upon submission, you will receive a private 12-word cryptographic claim phrase. You will use this phrase to claim your cash bounty anonymously.": "এই পোর্টালটি আপনার নাম, ফোন নম্বর বা আইপি ঠিকানা কখনোই সংরক্ষণ করে না। ক্যামেরার EXIF মেটাডেটা ব্রাউজারেই মুছে ফেলা হয়। জমা দেওয়ার পর আপনি ১২-শব্দের গোপন কোড পাবেন, যা দিয়ে পরিচয় না জানিয়ে পুরস্কারের অর্থ তোলা যাবে।",
    "Dedicated on-site voice assistant: Speak your observation or listen to step-by-step audio guidance.": "সাইট কর্মী ও সাধারণ নাগরিকদের জন্য ভয়েস সুবিধা: বাংলায় কথা বলে সরাসরি অভিযোগ জানান অথবা অডিও নির্দেশনা শুনুন।",
