    "Your submission has been sealed with zero-knowledge cryptography. No name, phone number, or identity was stored. Write down or copy this 12-word seed phrase. It is your only cryptographic proof to claim your 10% cash bounty when penalties are recovered.": "আপনার অভিযোগ জিরো-নলেজ ক্রিপ্টোগ্রাফি দিয়ে সুরক্ষিত করা হয়েছে। কোনও নাম, ফোন নম্বর বা পরিচয় সংরক্ষণ করা হয়নি। এই ১২-শব্দের বীজ বাক্যাংশটি লিখে রাখুন বা অনুলিপি করুন। জরিমানা আদায় হলে আপনার ১০% নগদ পুরষ্কার দাবি করার এটিই একমাত্র ক্রিপ্টোগ্রাফিক প্রমাণ।",
