    "Standard:": "ಮಾನದಂಡ:",
    "Zero-Knowledge Whistleblower Bounty Marketplace": "ಶೂನ್ಯ-ಜ್ಞಾನ ವಿಸ್ಲ್‌ಬ್ಲೋವರ್ ಬಹುಮಾನ ಮಾರುಕಟ್ಟೆ",
    "Zero-Knowledge Anti-Doxxing Guarantee (CVC Whistleblower Norms)": "ಶೂನ್ಯ-ಜ್ಞಾನ ಗುರುತು ಗೌಪ್ಯತೆ ಖಾತರಿ (ಸಿವಿಸಿ ನಿಯಮಗಳು)",
    "Zero-Knowledge Anti-Spoofing Guarantee (CVC Whistleblower Norms)": "ಶೂನ್ಯ-ಜ್ಞಾನ ವಂಚನೆ ವಿರೋಧಿ ಖಾತರಿ (ಸಿವಿಸಿ ನಿಯಮಗಳು)",
    "Whistleblower Legal Safeguards": "ವಿಸ್ಲ್‌ಬ್ಲೋವರ್ ಕಾನೂನು ರಕ್ಷಣೆಗಳು",
    "Whistleblower Legal Safeguards (CVC / GFR 2017)": "ವಿಸ್ಲ್‌ಬ್ಲೋವರ್ ಕಾನೂನು ರಕ್ಷಣೆಗಳು (ಕೇಂದ್ರ ಜಾಗೃತ ಆಯೋಗ ಸಿವಿಸಿ)",
    "Verified Watchdog Bounties": "ದೃಢೀಕೃತ ವೀಕ್ಷಕರ ಬಹುಮಾನಗಳು",
    "Multilingual Voice Assistant": "ಬಹುಭಾಷಾ ಧ್ವನಿ ಸಹಾಯಕ (ವಾಯ್ಸ್ ಸೌಲಭ್ಯ)",
    "Drop Evidence": "ರಹಸ್ಯ ಸಾಕ್ಷ್ಯ ಸಲ್ಲಿಸಿ",
    "Claim 10% Bounty": "10% ಬಹುಮಾನವನ್ನು ಕ್ಲೈಮ್ ಮಾಡಿ",
    "Confidential evidence drop for construction laborers, truck operators, and vigilant citizens. Earn a 10% statutory recovery bounty on seized contractor bank guarantees with zero identity disclosure.": "ನಿರ್ಮಾಣ ಕಾರ್ಮಿಕರು, ವಾಹನ ಚಾಲಕರು ಮತ್ತು ಜಾಗೃತ ನಾಗರಿಕರಿಗೆ ರಹಸ್ಯ ಪುರಾವೆ ಸಲ್ಲಿಕೆ. ಯಾವುದೇ ಗುರುತನ್ನು ಬಹಿರಂಗಪಡಿಸದೆ ಮುಟ್ಟುಗೋಲು ಹಾಕಿಕೊಂಡ ಗುತ್ತಿಗೆದಾರರ ಬ್ಯಾಂಕ್ ಗ್ಯಾರಂಟಿ ಮೇಲೆ 10% ಶಾಸನಬದ್ಧ ನಗದು ಬಹುಮಾನವನ್ನು ಪಡೆಯಿರಿ.",
    "This channel does NOT record your name, phone number, or IP address. EXIF camera metadata is scrubbed automatically in your browser. Upon submission, you will receive a private 12-word cryptographic claim phrase. You will use this phrase to claim your cash bounty anonymously.": "ಈ ಪೋರ್ಟಲ್ ನಿಮ್ಮ ಹೆಸರು, ಫೋನ್ ಸಂಖ್ಯೆ ಅಥವಾ ಐಪಿ ವಿಳಾಸವನ್ನು ಎಂದಿಗೂ ಸಂಗ್ರಹಿಸುವುದಿಲ್ಲ. ಕ್ಯಾಮೆರಾ EXIF ಮೆಟಾಡೇಟಾವನ್ನು ನಿಮ್ಮ ಬ್ರೌಸರ್‌ನಲ್ಲಿ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ತೆಗೆದುಹಾಕಲಾಗುತ್ತದೆ. ಸಲ್ಲಿಕೆಯ ನಂತರ ನೀವು 12-ಪದಗಳ ರಹಸ್ಯ ಕ್ಲೈಮ್ ಕೋಡ್ ಪಡೆಯುತ್ತೀರಿ, ಇದರ ಮೂಲಕ ಗುರುತು ಬಹಿರಂಗಪಡಿಸದೆ ನಗದು ಬಹುಮಾನ ಪಡೆಯಬಹುದು.",
    "Dedicated on-site voice assistant: Speak your observation or listen to step-by-step audio guidance.": "ಕಾರ್ಯಸ್ಥಳದ ಕಾರ್ಮಿಕರು ಮತ್ತು ಸಾರ್ವಜನಿಕರಿಗೆ ಧ್ವನಿ ಸೌಲಭ್ಯ: ಕನ್ನಡದಲ್ಲಿ ಮಾತನಾಡಿ ನೇರವಾಗಿ ದೂರು ನೀಡಿ ಅಥವಾ ಆಡಿಯೋ ಸೂಚನೆಗಳನ್ನು ಆಲಿಸಿ.",
    "Listen Voice Guide": "ಆಲಿಸಿ (ಧ್ವನಿ ಮಾರ್ಗದರ್ಶಿ)",
    "Stop Voice Guide": "ಆಡಿಯೋ ನಿಲ್ಲಿಸಿ",
    "Speak to Report": "ಮಾತನಾಡಿ ದೂರು ನೀಡಿ",
