    "Statutory evidence protocol: Camera and proof uploads require active device GPS to prevent falsified reports. Coordinates link the contractor and invoke the 36-month Defect Liability Period (DLP).": "ಶಾಸನಬದ್ಧ ಸಾಕ್ಷ್ಯ ನಿಯಮ: ಸುಳ್ಳು ದೂರುಗಳನ್ನು ತಡೆಗಟ್ಟಲು ಕ್ಯಾಮೆರಾ ಮತ್ತು ಫೋಟೋ ಅಪ್‌ಲೋಡ್‌ಗೆ ಜಿಪಿಎಸ್ ಆನ್ ಆಗಿರುವುದು ಕಡ್ಡಾಯ. ಇದು ಗುತ್ತಿಗೆದಾರರ 36 ತಿಂಗಳ ದೋಷ ಹೊಣೆಗಾರಿಕೆ ಅವಧಿಯನ್ನು (DLP) ನೇರವಾಗಿ ಜಾರಿಗೊಳಿಸುತ್ತದೆ.",
